INSERT INTO counseling_sessions (id, ticket_number, student_id, student_name, student_class, counselor_id, counselor_name, type, domain, session_date, session_time, location, status, problem_summary, confidential_notes, action_plan, outcome_summary, follow_up_date, created_at) VALUES ('cs-1', 'BK-2025-001', 's-1', 'Rizky Pratama', 'XI RPL 1', 'u-2', 'Siti Rahmawati, S.Pd., Kons.', 'individual', 'karier', '2025-02-14', '09:30', 'Ruang BK - Konseling Individu 1', 'completed', 'Konsultasi rencana PKL (Praktek Kerja Lapangan) dan pilihan universitas/pekerjaan setelah lulus SMK.', 'Siswa memiliki minat kuat di web development. Mengalami keraguan antara langsung bekerja membantu ekonomi keluarga atau kuliah malam. Telah diberikan arahan program beasiswa industri.', 'Membantu siswa menyusun portofolio GitHub dan mendaftar program magang mitra industri.', 'Siswa merasa lebih tenang dan memiliki gambaran jalur karier terukur.', NULL, '2025-02-10T11:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO counseling_sessions (id, ticket_number, student_id, student_name, student_class, counselor_id, counselor_name, type, domain, session_date, session_time, location, status, problem_summary, confidential_notes, action_plan, outcome_summary, follow_up_date, created_at) VALUES ('cs-2', 'BK-2025-002', 's-3', 'Dimas Bagus Saputra', 'XI RPL 1', 'u-2', 'Siti Rahmawati, S.Pd., Kons.', 'individual', 'belajar', '2025-02-18', '11:00', 'Ruang BK - Konseling Individu 2', 'in_progress', 'Tindak lanjut rujukan wali kelas terkait penurunan kehadiran dan motivasi belajar pada mata pelajaran produktif.', 'Siswa sering begadang bermain game online hingga dini hari karena masalah komunikasi dengan orang tua yang sibuk bekerja. Perlu pendekatan pembiasaan jadwal teratur.', 'Membuat time schedule harian bersama siswa dan jadwalkan sesi pemanggilan orang tua dengan pendekatan suportif.', '', '2025-02-25', '2025-02-12T14:20:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO counseling_sessions (id, ticket_number, student_id, student_name, student_class, counselor_id, counselor_name, type, domain, session_date, session_time, location, status, problem_summary, confidential_notes, action_plan, outcome_summary, follow_up_date, created_at) VALUES ('cs-3', 'BK-2025-003', 's-2', 'Anisa Maharani', 'XI RPL 1', 'u-2', 'Siti Rahmawati, S.Pd., Kons.', 'individual', 'pribadi', '2025-02-20', '13:00', 'Ruang BK - Konseling Individu 1', 'scheduled', 'Manajemen stres menghadapi ujian tengah semester dan beban proyek kelompok.', 'Siswa mengalami perfeksionisme berlebih dan kecemasan fisik ringan (sulit tidur). Pendekatan relaksasi breathing dan kognitif reframing.', 'Latihan teknik relaksasi 4-7-8 dan penjadwalan skala prioritas tugas.', '', NULL, '2025-02-17T09:15:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO counseling_sessions (id, ticket_number, student_id, student_name, student_class, counselor_id, counselor_name, type, domain, session_date, session_time, location, status, problem_summary, confidential_notes, action_plan, outcome_summary, follow_up_date, created_at) VALUES ('cs-4', 'BK-2025-004', 's-5', 'Muhammad Farhan', 'X TKJ 1', 't-bk2', 'Fajar Nugroho, S.Pd.', 'individual', 'sosial', '2025-02-22', '10:00', 'Ruang BK - Konseling Individu 2', 'scheduled', 'Penyesuaian diri dan interaksi sosial dengan teman sebaya di kelas baru.', '', '', '', NULL, '2025-02-19T08:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO referrals (id, referral_number, student_id, student_name, student_class, referred_by_teacher_id, referred_by_teacher_name, counselor_id, counselor_name, reason, indicators, urgency, status, counselor_feedback, created_at, updated_at) VALUES ('ref-1', 'RUJ-2025-01', 's-3', 'Dimas Bagus Saputra', 'XI RPL 1', 'u-3', 'Ahmad Fauzi, S.Pd. (Wali Kelas)', 'u-2', 'Siti Rahmawati, S.Pd., Kons.', 'Siswa sudah 4 kali terlambat dalam 2 minggu terakhir dan tampak mengantuk berat di kelas. Nilai harian mata pelajaran basis data turun drastis.', '["Sering Terlambat","Penurunan Prestasi","Tampak Mengantuk / Lelah di Kelas"]'::jsonb, 'high', 'scheduled', 'Rujukan diterima. Jadwal konseling individu telah dibuat pada tanggal 18 Februari 2025 pukul 11:00 WIB.', '2025-02-11T13:45:00Z', '2025-02-12T08:10:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO referrals (id, referral_number, student_id, student_name, student_class, referred_by_teacher_id, referred_by_teacher_name, counselor_id, counselor_name, reason, indicators, urgency, status, counselor_feedback, created_at, updated_at) VALUES ('ref-2', 'RUJ-2025-02', 's-5', 'Muhammad Farhan', 'X TKJ 1', 't-2', 'Nurul Hidayati, M.Pd. (Wali Kelas)', 't-bk2', 'Fajar Nugroho, S.Pd.', 'Siswa sering menyendiri saat istirahat dan belum memiliki kelompok kerja tugas kelompok. Tampak pasif dan ragu berkomunikasi.', '["Menarik Diri","Kesulitan Beradaptasi"]'::jsonb, 'medium', 'accepted', 'Sedang disiapkan sesi bimbingan kelompok kecil untuk integrasi teman sebaya.', '2025-02-18T10:15:00Z', '2025-02-18T14:30:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO student_cases (id, case_number, title, student_id, student_name, student_class, category, priority, status, assigned_counselor_id, assigned_counselor_name, incident_date, chronology_summary, confidential_details, interventions, resolution_notes, created_at, updated_at) VALUES ('case-1', 'KASUS-2025-001', 'Penanganan Ketidakhadiran Berulang & Indikasi Adiksi Gawai', 's-3', 'Dimas Bagus Saputra', 'XI RPL 1', 'kedisiplinan', 'tinggi', 'penanganan', 'u-2', 'Siti Rahmawati, S.Pd., Kons.', '2025-02-10', 'Ditemukan ketidakhadiran tanpa keterangan sebanyak 5 hari dalam bulan berjalan dan 4 kali keterlambatan berurutan.', 'Orang tua siswa telah dihubungi melalui telepon. Terungkap siswa mengalami konflik internal keluarga pasca perceraian orang tua dan melarikan diri ke game online hingga larut malam.', '[{"date":"2025-02-12","action":"Pemanggilan siswa dan konseling awal","by":"Siti Rahmawati, S.Pd., Kons.","result":"Siswa terbuka mengenai situasi di rumah dan berkomitmen mengatur alarm tidur."},{"date":"2025-02-15","action":"Konferensi kasus internal dengan Wali Kelas","by":"Siti Rahmawati, S.Pd., Kons. & Ahmad Fauzi, S.Pd.","result":"Wali kelas memberikan keringanan pengerjaan tugas remedial secara berkala."}]'::jsonb, '', '2025-02-11T09:00:00Z', '2025-02-15T11:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO student_cases (id, case_number, title, student_id, student_name, student_class, category, priority, status, assigned_counselor_id, assigned_counselor_name, incident_date, chronology_summary, confidential_details, interventions, resolution_notes, created_at, updated_at) VALUES ('case-2', 'KASUS-2025-002', 'Dugaan Perselisihan Verbal Antar Siswa di Kantin', 's-5', 'Muhammad Farhan', 'X TKJ 1', 'sosial_perilaku', 'sedang', 'investigasi', 't-bk2', 'Fajar Nugroho, S.Pd.', '2025-02-17', 'Laporan percekcokan mulut saat antre di kantin sekolah dengan siswa kelas lain.', 'Terjadi salah paham mengenai antrean pesanan makanan, tidak ada kontak fisik kekerasan. Kedua pihak sudah ditenangkan.', '[{"date":"2025-02-18","action":"Mediasi tatap muka kedua pihak di ruang BK","by":"Fajar Nugroho, S.Pd.","result":"Kedua belah pihak saling meminta maaf dan sepakat menyelesaikan secara kekeluargaan."}]'::jsonb, '', '2025-02-17T15:00:00Z', '2025-02-18T16:00:00Z') ON CONFLICT (id) DO NOTHING;
