INSERT INTO assessments (id, title, code, description, target_class, questions, deadline, status, submission_count, total_target) VALUES ('asm-1', 'Asesmen Gaya Belajar Siswa (Visual, Auditori, Kinestetik)', 'GAYA-BELAJAR-VAK', 'Kuesioner diagnostik non-kognitif untuk memetakan modalitas belajar utama peserta didik guna menyesuaikan strategi bimbingan dan metode ajar.', 'Semua Siswa', '[{"id":"q1","text":"Ketika mempelajari sesuatu yang baru, cara yang paling membantu saya adalah:","type":"multiple_choice","options":[{"value":"V","label":"Melihat diagram, bagan, atau demonstrasi visual"},{"value":"A","label":"Mendengarkan penjelasan guru atau podcast audio"},{"value":"K","label":"Mencoba langsung mempraktikkan atau menyentuh alatnya"}]},{"id":"q2","text":"Saat sedang berkonsentrasi mengerjakan tugas sekolah:","type":"multiple_choice","options":[{"value":"V","label":"Saya terganggu oleh pemandangan ruangan yang berantakan"},{"value":"A","label":"Saya sangat terganggu oleh suara bising di sekitar"},{"value":"K","label":"Saya tidak bisa diam duduk terlalu lama tanpa bergerak"}]},{"id":"q3","text":"Ketika mengingat kembali materi pelajaran kemarin:","type":"multiple_choice","options":[{"value":"V","label":"Saya membayangkan letak tulisan atau gambar di buku catatan"},{"value":"A","label":"Saya mengingat suara atau kalimat yang diucapkan guru"},{"value":"K","label":"Saya mengingat kegiatan fisik atau eksperimen yang dilakukan"}]},{"id":"q4","text":"Buku atau referensi belajar yang paling saya sukai adalah:","type":"multiple_choice","options":[{"value":"V","label":"Banyak ilustrasi warna, infografis, dan tata letak rapi"},{"value":"A","label":"Audiobook, diskusi kelompok, atau tanya jawab lisan"},{"value":"K","label":"Buku panduan praktikum dan simulasi langsung"}]}]'::jsonb, '2025-03-15', 'active', 142, 175) ON CONFLICT (id) DO NOTHING;
INSERT INTO assessments (id, title, code, description, target_class, questions, deadline, status, submission_count, total_target) VALUES ('asm-2', 'Angket Kebutuhan Peserta Didik (AKPD) Semester Genap', 'AKPD-2025', 'Identifikasi kebutuhan mendesak siswa pada 4 bidang bimbingan: Pribadi, Sosial, Belajar, dan Karier.', 'Kelas XI & XII', '[{"id":"akpd-1","text":"Saya merasa bingung menentukan pilihan jurusan perguruan tinggi atau lapangan kerja setelah tamat sekolah.","type":"multiple_choice","options":[{"value":"1","label":"Sangat Tidak Sesuai"},{"value":"2","label":"Tidak Sesuai"},{"value":"3","label":"Sesuai"},{"value":"4","label":"Sangat Sesuai"}]},{"id":"akpd-2","text":"Saya sering menunda-nunda pengerjaan tugas sekolah sampai mendekati batas waktu pengumpulan.","type":"multiple_choice","options":[{"value":"1","label":"Sangat Tidak Sesuai"},{"value":"2","label":"Tidak Sesuai"},{"value":"3","label":"Sesuai"},{"value":"4","label":"Sangat Sesuai"}]},{"id":"akpd-3","text":"Saya merasa cemas atau takut ketika harus berbicara atau presentasi di depan kelas.","type":"multiple_choice","options":[{"value":"1","label":"Sangat Tidak Sesuai"},{"value":"2","label":"Tidak Sesuai"},{"value":"3","label":"Sesuai"},{"value":"4","label":"Sangat Sesuai"}]}]'::jsonb, '2025-03-30', 'active', 88, 105) ON CONFLICT (id) DO NOTHING;
INSERT INTO assessment_submissions (id, assessment_id, assessment_title, student_id, student_name, student_class, submitted_at, answers, result_summary) VALUES ('sub-1', 'asm-1', 'Asesmen Gaya Belajar Siswa (Visual, Auditori, Kinestetik)', 's-1', 'Rizky Pratama', 'XI RPL 1', '2025-02-10T14:00:00Z', '{"q1":"V","q2":"V","q3":"V","q4":"K"}'::jsonb, '{"dominantType":"Visual (75%)","needsAnalysis":["Memerlukan diagram alur dan mind mapping untuk pemahaman kode pemrograman"],"counselorRecommendation":"Gunakan catatan visual berwarna dan ringkasan infografis saat belajar mandiri."}'::jsonb) ON CONFLICT (id) DO NOTHING;
